    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AĈZ</span> و <span dir=\"ltr\" class=\"expr pt\">AĈT</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">AĈZ = 122°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CK)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈZ</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CH)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈT</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">HĈK.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [CK)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈZ</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈZ = 122°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CK)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈZ</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈZ = 122°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈK = 122° : 2 = 61°</span>"},{"quoi":"القاعدة","math":"زاويتان متكاملتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AĈZ</span> و <span dir=\"ltr\" class=\"expr pt\">AĈT</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">AĈZ = 122°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈT = 180° - 122° = 58°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CH)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈT</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈT = 58°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈH = 58° : 2 = 29°</span>"},{"quoi":"القاعدة","math":"إذا كانت زاويتان متجاورتين فإنّ قيس الزاوية الكبرى يساوي مجموع قيسيهما"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AĈK</span> و <span dir=\"ltr\" class=\"expr pt\">AĈH</span> متجاورتان  و  <span dir=\"ltr\" class=\"expr pt\">AĈK = 61°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈH = 29°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">HĈK = 61° + 29° = 90°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">HĈK = 90°</span>"}],
